tool_input.command:
cat > forgemyspec-board.yaml <<'EOF'
requirements:
  - id: R1
    status: done
    title: "REST Blog API (blog_api.py)"
    quote: "Build a REST Blog API in Python using only the standard library (http.server + sqlite3). CRUD for posts, X-API-Key auth, JSON bodies, localhost:8080, single file blog_api.py."
    steps:
      - {do: "Spec written and lint clean", check: "cmd: python3 -m forgemyspec lint forgemyspec-bundle/blog-api/spec.yaml --formal"}
      - {do: "User approves the spec (spec.lock)", check: "cmd: python3 -m forgemyspec lock --check forgemyspec-bundle/blog-api"}
      - {do: "Implement blog_api.py and boundary tests", check: "cmd: python3 -m unittest discover -s tests"}
      - {do: "Gate passes", check: "cmd: python3 -m forgemyspec gate forgemyspec-bundle/blog-api"}
EOF
export PYTHONPATH=.forgemyspec/harness; python3 -m forgemyspec board start R1 >/dev/null 2>&1; python3 -m forgemyspec board verify >/dev/null 2>&1; python3 -m forgemyspec board 2>&1
